/**
 * Handle a journal entry submission from the dialog system
 * Called when player finishes writing in the journal
 */
_handleJournalSubmit(entry) {
    // Record the emotion in the system
    const recorded = this.emotion.recordEmotion(
        entry.emotionId,
        entry.intensity,
        entry.description,
        'journal'
    );

    const emotion = Object.values(EmotionTypes).find(e => e.id === entry.emotionId);
    this.hud.notify(
        `Journal entry recorded: ${emotion ? emotion.name : entry.emotionId} (${entry.intensity}%)`,
        emotion ? emotion.color : '#e8c88a'
    );
    this.hud.hideJournalHint();

    // Check immediately if crystallizable
    const crystallizable = this.emotion.getCrystallizableEmotions();
    if (crystallizable.length > 0) {
        setTimeout(() => {
            this.dialog.show({
                speaker: '✦ Inner Voice',
                speakerColor: '#e8c88a',
                text: `You have enough ${crystallizable[0].emotion.name} energy to crystallize into a seed.\n\nWould you like to crystallize it now?`,
                style: 'inner',
                choices: [
                    { text: `❖ Crystallize ${crystallizable[0].emotion.name} Seed`, action: 'crystallize' },
                    { text: '◇ Save for later', action: 'close' }
                ]
            });
            this.gameState = 'dialog';
        }, 800);
    }

    // Update quest progress
    this.quests.updateProgress('journal_entry', { count: this.emotion.getEntryCount() });
}

