/**
 * Handle a journal entry submission from the dialog system
 * Every journal entry creates a seed. Quality depends on intensity + meditation.
 */
_handleJournalSubmit(entry) {
    // Record emotion and create seed
    const seed = this.emotion.recordEmotion(
        entry.emotionId,
        entry.intensity,
        entry.description,
        'journal'
    );

    const emotion = Object.values(EmotionTypes).find(e => e.id === entry.emotionId);
    this.hud.notify(
        `✨ Seed created: ${emotion ? emotion.name : entry.emotionId} (Quality: ${Math.round(seed.quality)})`,
        emotion ? emotion.color : '#88cc44'
    );
    this.hud.hideJournalHint();

    // Tutorial step 1: first journal complete
    if (!this.tutorial.firstJournal) {
        this.tutorial.firstJournal = true;
        setTimeout(() => {
            this.dialog.show({
                speaker: '✦ Inner Voice',
                speakerColor: '#e8c88a',
                text: `A ${emotion ? emotion.name : ''} Karmic Seed has formed in your inventory.\n\nQuality: ${Math.round(seed.quality)}/100\n\nHigher quality fruit gives better stat boosts.\n\nYou can meditate (hold M) to raise seed quality.\n\nFind an empty garden plot and press Space to plant it.`,
                style: 'inner',
                choices: [
                    { text: '🌱 Try planting it now', action: 'close' },
                    { text: 'Show me how to meditate first', action: 'tutorial_meditation' }
                ]
            });
            this.gameState = 'dialog';
        }, 800);
    }

    // Update quest progress
    this.quests.updateProgress('journal_entry', { count: this.emotion.getEntryCount() });
}

