_handleDialogChoice(action, choice) {
    if (action === 'open_journal') {
        this._openJournal();
    } else if (action === 'crystallize') {
        const crystallizable = this.emotion.getCrystallizableEmotions();
        if (crystallizable.length > 0) {
            const seed = this.emotion.crystallizeSeed(crystallizable[0].emotionId);
            if (seed) {
                this.hud.notify(`Crystallized a ${crystallizable[0].emotion.name} Seed! Quality: ${seed.quality}`, crystallizable[0].emotion.color);
                this.quests.updateProgress('seed_created', { emotionId: seed.emotionId });
                this._spawnParticles(this.player.x, this.player.y, seed.emotionId);
            }
        }
    } else if (action === 'reflect') {
        // Open journal to process a specific recent entry
        this._openJournal();
    }
}

